/* ---------------- Protected Route ---------------- */
const ProtectedRoute = ({ children, requiredRole }) => {
  let token;
  let redirectPath = "/shop";

  if (requiredRole === "user") {
    token = localStorage.getItem("userToken") || (localStorage.getItem("role") === "patient" ? localStorage.getItem("token") : null);
  } else if (requiredRole === "centre") {
    token = localStorage.getItem("centreToken") || (localStorage.getItem("role") === "centre" ? localStorage.getItem("token") : null);
    redirectPath = "/";
  } else if (requiredRole === "admin") {
    token = localStorage.getItem("adminToken");
    redirectPath = "/manage4ceps-admin";
  } else if (requiredRole === "seller") {
    token = localStorage.getItem("sellerToken") || (localStorage.getItem("role") === "seller" ? localStorage.getItem("token") : null);
    redirectPath = "/shop";
  }

  if (!token || isTokenExpired(token)) return <Navigate to={redirectPath} replace />;

  return children;
};

